<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ApiClient, errorMessage } from '../api'
import { dateTime, productAvailable } from '../domain'
import type { Job, NoticeSink, Product, Session } from '../types'
import DialogShell from '../components/DialogShell.vue'
import Icon from '../components/Icon.vue'
interface SpeechTemplate { id: string; shop_id: string; name: string; body: string; version: number; updated_at: string }
const props = defineProps<{ api: ApiClient; shopId: string; products: Product[]; sessions: Session[]; reload: () => Promise<void>; notify: NoticeSink }>()
const records = ref<SpeechTemplate[]>([]), loading = ref(true), error = ref(''), formError = ref(''), busy = ref(''), open = ref(false)
const editing = ref<SpeechTemplate | null>(null), deleting = ref<SpeechTemplate | null>(null), applying = ref<SpeechTemplate | null>(null)
const sessionId = ref(''), productId = ref(''), form = reactive({ name: '', body: '' })
const fields = [{ key: 'title', label: '商品名称' }, { key: 'sku', label: 'SKU' }, { key: 'price', label: '价格（元）' }, { key: 'stock', label: '库存' }, { key: 'specs', label: '规格' }, { key: 'description', label: '商品说明' }]
const validSession = computed(() => props.sessions.find(s => s.id === sessionId.value)?.status === 'active')
const validProduct = computed(() => { const product = props.products.find(p => p.id === productId.value); return !!product && productAvailable(product) })
watch(() => props.sessions, list => { if (!list.some(s => s.id === sessionId.value)) sessionId.value = list.find(s => s.status === 'active')?.id ?? '' }, { immediate: true })
watch(() => props.products, list => { if (!list.some(p => p.id === productId.value)) productId.value = list.find(p => productAvailable(p))?.id ?? '' }, { immediate: true })
async function load() { loading.value = true; error.value = ''; try { records.value = await props.api.request<SpeechTemplate[]>('/templates', { query: { shop_id: props.shopId } }) } catch (cause) { error.value = errorMessage(cause) } finally { loading.value = false } }
onMounted(load)
function edit(record: SpeechTemplate | null) { editing.value = record; form.name = record?.name ?? ''; form.body = record?.body ?? ''; formError.value = ''; open.value = true }
async function save() {
  if (busy.value) return; formError.value = ''
  try {
    if (!form.name.trim() || !form.body.trim()) throw new Error('请填写模板名称与正文。')
    const remaining = form.body.replace(/\{(title|sku|price|stock|specs|description)\}/g, '')
    if (/[{}]/.test(remaining)) throw new Error('模板包含未知字段或不成对的大括号。只使用下方列出的六种字段。')
    busy.value = 'save'; await props.api.request(editing.value ? '/templates/' + editing.value.id : '/templates', { method: editing.value ? 'PUT' : 'POST', body: { shop_id: props.shopId, name: form.name.trim(), body: form.body.trim(), version: editing.value?.version ?? 0 } }); open.value = false; await load(); props.notify('模板已保存，应用时会读取当前商品事实并创建待审核草稿。')
  } catch (cause) { formError.value = errorMessage(cause) } finally { busy.value = '' }
}
async function remove() { if (!deleting.value || busy.value) return; busy.value = 'delete'; formError.value = ''; try { await props.api.request('/templates/' + deleting.value.id, { method: 'DELETE', query: { shop_id: props.shopId, version: String(deleting.value.version) } }); deleting.value = null; await load(); props.notify('模板已删除。') } catch (cause) { formError.value = errorMessage(cause) } finally { busy.value = '' } }
async function apply() { if (!applying.value || busy.value || !validSession.value || !validProduct.value) return; busy.value = 'apply'; formError.value = ''; try { const job = await props.api.request<Job>('/templates/' + applying.value.id + '/apply', { method: 'POST', body: { shop_id: props.shopId, session_id: sessionId.value, product_id: productId.value } }); applying.value = null; await props.reload(); props.notify(job.status === 'draft' ? '已按当前商品事实创建待审核稿，请到直播工作台核对并批准。' : '任务已保存，状态为 ' + job.status + '，请到工作台检查。', 'info') } catch (cause) { formError.value = errorMessage(cause) } finally { busy.value = '' } }
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">SPEECH TEMPLATES</div><h1>话术模板</h1><p>复用表达结构，每次重新填入当前商品事实并审核。</p></div><button class="button primary" @click="edit(null)"><Icon name="plus" />新增模板</button></div><div class="info-strip">模板应用会在服务端读取当前商品和人格快照，只创建人工待审核稿，不调用 DeepSeek、不自动合成或播报。</div><div v-if="error" class="alert error" role="alert">{{ error }}<button class="inline-button" @click="load">重试</button></div>
  <section class="panel"><div class="panel-title"><h2>本店话术结构</h2><button class="button ghost small" :disabled="loading" @click="load">刷新</button></div><div v-if="loading" class="empty-state compact">正在读取模板…</div><div v-else-if="!records.length" class="empty-state"><Icon name="book" :size="32" /><h3>保存常用的介绍结构</h3><p>把名称、价格和规格写成字段，避免复制旧话术时沿用过期价格。</p><button class="button secondary" @click="edit(null)">新增第一个模板</button></div><div v-else class="knowledge-list"><article v-for="record in records" :key="record.id" class="knowledge-item"><div class="knowledge-copy"><div class="record-badges"><span class="badge neutral">v{{ record.version }}</span><small class="muted">{{ dateTime(record.updated_at) }}</small></div><h3>{{ record.name }}</h3><p>{{ record.body }}</p></div><div class="row-actions"><button class="button secondary small" @click="applying = record; formError = ''">应用为草稿</button><button class="button ghost small" @click="edit(record)">编辑</button><button class="button ghost small danger-text" @click="deleting = record; formError = ''">删除</button></div></article></div></section>
  <DialogShell v-if="open" :title="editing ? '编辑话术模板' : '新增话术模板'" @close="!busy && (open = false)"><form class="form-stack" @submit.prevent="save"><label>模板名称<input v-model="form.name" required maxlength="100" /></label><label>话术正文<textarea v-model="form.body" required maxlength="2000" rows="7" placeholder="例如：这款 {title} 的价格是 {price} 元，规格为 {specs}。" /></label><div class="suggestion-row"><button v-for="field in fields" :key="field.key" type="button" class="suggestion" @click="form.body += '{' + field.key + '}'">{{ field.label }} {{ '{' + field.key + '}' }}</button></div><p class="hint">只支持上述六个字段，不支持脚本、表达式或任意路径。替换后内容仍要经过长度与事实有效性核验。</p><div v-if="formError" class="alert error" role="alert">{{ formError }}</div><div class="form-actions"><button type="button" class="button secondary" :disabled="!!busy" @click="open = false">取消</button><button class="button primary" :disabled="!!busy">{{ busy === 'save' ? '保存中…' : '保存模板' }}</button></div></form></DialogShell>
  <DialogShell v-if="applying" title="按当前商品生成模板草稿" @close="!busy && (applying = null)"><form class="form-stack" @submit.prevent="apply"><p>{{ applying.name }} · v{{ applying.version }}</p><label>本地场次<select v-model="sessionId" required><option value="">先创建运行中的场次</option><option v-for="session in sessions" :key="session.id" :value="session.id" :disabled="session.status !== 'active'">{{ session.title }}</option></select></label><label>关联商品<select v-model="productId" required><option value="">先添加可用商品</option><option v-for="product in products" :key="product.id" :value="product.id" :disabled="!productAvailable(product)">{{ product.title }}</option></select></label><p class="hint">应用不等于批准。到直播工作台检查替换后的价格、规格和承诺，再人工批准。</p><div v-if="formError" class="alert error" role="alert">{{ formError }}</div><div class="form-actions"><button type="button" class="button secondary" :disabled="!!busy" @click="applying = null">取消</button><button class="button primary" :disabled="!!busy || !validSession || !validProduct">{{ busy === 'apply' ? '创建中…' : '创建待审核草稿' }}</button></div></form></DialogShell>
  <DialogShell v-if="deleting" title="删除话术模板？" @close="!busy && (deleting = null)"><div class="form-stack"><p>确认删除“{{ deleting.name }}”。已有播报任务仍需按其自身状态处理。</p><div v-if="formError" class="alert error" role="alert">{{ formError }}</div><div class="form-actions"><button class="button secondary" :disabled="!!busy" @click="deleting = null">取消</button><button class="button danger" :disabled="!!busy" @click="remove">{{ busy === 'delete' ? '删除中…' : '确认删除' }}</button></div></div></DialogShell>
</template>
